cypress_script:
describe('HTTP Status Codes Page', () => {
  it('should navigate to 200 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('200').click();
    cy.url().should('include', '/status_codes/200');
    cy.get('headings').should('contain', 'Status Codes');
  });
  it('should not navigate to a non-existent status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('999').click({ force: true });
    cy.url().should('not.include', '/status_codes/999');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('HTTP Status Codes Page', () => {
  test('should navigate to 200 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=200');
    await page.waitForURL(/.*status_codes\/200/);
    await page.locator('headings').isVisible();
  });
  test('should not navigate to a non-existent status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('text=999');
    await page.waitForTimeout(1000);
    await page.url().then(url => {
      expect(url).not.toContain('/status_codes/999');
    });
  });
});
